   ========================================== */
.attention-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.attention-item {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    padding: 12px;
    border-radius: 8px;
    border: 1px solid var(--app-border);
    transition: background 0.15s ease;
