.form-row { width: 100%; }

.form-row-2 {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
}

.form-col {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.field-error {
    color: #dc2626;
    font-size: 0.75rem;
    margin-top: 4px;
    display: block;
}

/* ==========================================
   VIEW TICKET DIALOG
   ========================================== */
.ticket-detail {
    display: flex;
    flex-direction: column;
    gap: 16px;
    padding: 8px 0;
    min-width: 480px;
}

.detail-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
}

.detail-field {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.detail-label {
    font-size: 0.72rem;
    font-weight: 600;
    color: var(--app-text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.detail-value {
    font-size: 0.95rem;
    color: var(--app-text-primary);
    font-weight: 500;
}

.detail-description {
    background: var(--app-bg);
    border-radius: 8px;
    padding: 12px;
    font-size: 0.875rem;
    color: var(--app-text-secondary);
    line-height: 1.6;
    border: 1px solid var(--app-border);
}

/* ==========================================
   LOADING
   ========================================== */
.loading-overlay {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 60px 24px;
    gap: 16px;
    color: var(--app-text-secondary);
}

.loading-spinner {
    width: 40px;
    height: 40px;
    border: 3px solid var(--app-border);
    border-top-color: var(--app-accent);
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
}

@keyframes spin { to { transform: rotate(360deg); } }

/* ==========================================
   TOAST NOTIFICATIONS
   ========================================== */
.app-toast {
    position: fixed;
    bottom: 24px;
    right: 24px;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 14px 20px;
    border-radius: 10px;
    background: var(--app-primary);
    color: white;
    box-shadow: 0 8px 24px rgba(0,0,0,0.2);
    z-index: 10000;
    font-size: 0.9rem;
    font-weight: 500;
    animation: toastIn 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    max-width: 380px;
    border-left: 4px solid var(--app-accent);
}

.app-toast.toast-success { background: #064e3b; border-left-color: #22c55e; }
.app-toast.toast-error   { background: #450a0a; border-left-color: #ef4444; }
.app-toast.toast-info    { background: var(--app-primary); border-left-color: var(--app-accent); }

.toast-icon { font-size: 1.2rem; flex-shrink: 0; }

@keyframes toastIn {
    from { opacity: 0; transform: translateX(40px) scale(0.95); }
    to   { opacity: 1; transform: translateX(0) scale(1); }
}

/* ==========================================
   CONFIRM DIALOG
   ========================================== */
.confirm-message {
    font-size: 0.95rem;
    color: var(--app-text-secondary);
    margin: 0;
    padding: 8px 0;
    line-height: 1.6;
}

.confirm-ticket-id {
    font-weight: 700;
    color: var(--app-primary);
    font-family: monospace;
}

/* ==========================================
   RESPONSIVE
   ========================================== */
@media (max-width: 1200px) {
    .kpi-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 900px) {
    .charts-row { grid-template-columns: 1fr; }
    .dashboard-bottom { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
    .main-content { padding: 16px; }
    .kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .form-row-2 { grid-template-columns: 1fr; }
    .search-input, .filter-select { min-width: unset; width: 100%; }
}"}

